CREATE OR REPLACE FUNCTION public.calculate_partner_metrics(p_partner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_total INTEGER;
  v_completed INTEGER;
  v_cancelled INTEGER;
  v_refunded INTEGER;
  v_on_time INTEGER;
  v_on_time_rate NUMERIC;
  v_defect_rate NUMERIC;
  v_refund_rate NUMERIC;
  v_quality_score NUMERIC;
  v_window_start TIMESTAMPTZ;
  v_window_days INTEGER := 90;
BEGIN
  v_window_start := NOW() - (v_window_days || ' days')::INTERVAL;
  
  SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'completed'), COUNT(*) FILTER (WHERE status = 'cancelled'), COUNT(*) FILTER (WHERE status IN ('refunded', 'refund_approved')), COUNT(*) FILTER (WHERE shipped_at IS NOT NULL AND shipped_at <= confirmed_at + INTERVAL '2 days')
  INTO v_total, v_completed, v_cancelled, v_refunded, v_on_time
  FROM public.orders WHERE seller_id = p_partner_id AND created_at >= v_window_start;
  
  IF v_total > 0 THEN
    v_on_time_rate := (v_on_time::NUMERIC / NULLIF((v_completed + v_cancelled), 0) * 100);
    v_refund_rate := (v_refunded::NUMERIC / v_total * 100);
  ELSE
    v_on_time_rate := 100.00;
    v_refund_rate := 0.00;
  END IF;
  
  SELECT CASE WHEN v_total > 0 THEN (COUNT(*)::NUMERIC / v_total * 100) ELSE 0.00 END INTO v_defect_rate
  FROM public.qos_violations WHERE partner_id = p_partner_id AND created_at >= v_window_start AND severity IN ('high', 'critical');
  
  v_quality_score := ((COALESCE(v_on_time_rate, 100) * 0.4) + ((100 - COALESCE(v_defect_rate, 0)) * 0.4) + ((100 - COALESCE(v_refund_rate, 0)) * 0.2));
  
  INSERT INTO public.partner_performance_metrics (partner_id, total_orders, completed_orders, cancelled_orders, refunded_orders, on_time_shipment_rate, defect_rate, refund_rate, overall_quality_score, qos_violation_count, rolling_window_days, metric_period_start, last_calculated_at)
  VALUES (p_partner_id, v_total, v_completed, v_cancelled, v_refunded, COALESCE(v_on_time_rate, 100), COALESCE(v_defect_rate, 0), COALESCE(v_refund_rate, 0), v_quality_score, (SELECT COUNT(*) FROM public.qos_violations WHERE partner_id = p_partner_id), v_window_days, v_window_start, NOW())
  ON CONFLICT (partner_id) DO UPDATE SET total_orders = EXCLUDED.total_orders, completed_orders = EXCLUDED.completed_orders, cancelled_orders = EXCLUDED.cancelled_orders, refunded_orders = EXCLUDED.refunded_orders, on_time_shipment_rate = EXCLUDED.on_time_shipment_rate, defect_rate = EXCLUDED.defect_rate, refund_rate = EXCLUDED.refund_rate, overall_quality_score = EXCLUDED.overall_quality_score, qos_violation_count = EXCLUDED.qos_violation_count, metric_period_start = EXCLUDED.metric_period_start, last_calculated_at = NOW(), updated_at = NOW();
END;
$function$
;
