CREATE OR REPLACE FUNCTION public.calculate_refund_eligible_until(p_order_id uuid, p_delivered_at timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_refund_window_days INTEGER;
  v_is_digital BOOLEAN;
BEGIN
  SELECT COALESCE(bool_or(p.is_digital), false) INTO v_is_digital
  FROM public.order_items oi
  JOIN public.products p ON p.id = oi.product_id
  WHERE oi.order_id = p_order_id;
  
  IF v_is_digital THEN
    v_refund_window_days := 14;
  ELSE
    v_refund_window_days := COALESCE((SELECT (value->>0)::INTEGER FROM public.system_config WHERE key = 'refund_window_days'), 30);
  END IF;
  
  RETURN p_delivered_at + (v_refund_window_days || ' days')::INTERVAL;
END;
$function$
;
