CREATE OR REPLACE FUNCTION public.check_and_cancel_unshipped_orders()
 RETURNS TABLE(cancelled_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_cancelled_count INTEGER := 0;
  v_max_days INTEGER;
BEGIN
  v_max_days := COALESCE(
    (SELECT value::INTEGER FROM public.system_config WHERE key = 'max_days_to_ship'),
    7
  );
  
  WITH cancelled_orders AS (
    UPDATE public.orders
    SET 
      status = 'cancelled',
      cancelled_at = NOW(),
      internal_notes = COALESCE(internal_notes || E'\n', '') || 'Auto-cancelled: Partner did not ship within ' || v_max_days || ' days'
    WHERE status = 'confirmed' AND created_at < NOW() - (v_max_days || ' days')::INTERVAL
    RETURNING id, buyer_id, total_amount, currency
  )
  SELECT COUNT(*)::INTEGER INTO v_cancelled_count FROM cancelled_orders;
  
  RETURN QUERY SELECT v_cancelled_count;
END;
$function$
;
