CREATE OR REPLACE FUNCTION public.check_refund_eligibility(p_order_id uuid)
 RETURNS TABLE(is_eligible boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order RECORD;
  v_has_active_refund BOOLEAN;
BEGIN
  SELECT o.* INTO v_order FROM public.orders o WHERE o.id = p_order_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'Order not found'; RETURN; END IF;
  IF v_order.status NOT IN ('delivered', 'completed') THEN RETURN QUERY SELECT false, 'Order must be delivered to request refund'; RETURN; END IF;
  IF v_order.refund_eligible_until < NOW() THEN RETURN QUERY SELECT false, 'Refund window has expired'; RETURN; END IF;
  SELECT EXISTS(SELECT 1 FROM public.refund_requests WHERE order_id = p_order_id AND status IN ('pending_partner', 'partner_approved', 'pending_admin')) INTO v_has_active_refund;
  IF v_has_active_refund THEN RETURN QUERY SELECT false, 'Refund request already in progress'; RETURN; END IF;
  RETURN QUERY SELECT true, 'Order is eligible for refund';
END;
$function$
;
