CREATE OR REPLACE FUNCTION public.initiate_refund(p_refund_request_id uuid, p_approved_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_refund_request RECORD;
  v_transaction_id UUID;
BEGIN
  SELECT rr.* INTO v_refund_request FROM public.refund_requests rr WHERE rr.id = p_refund_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund request not found'; END IF;
  
  UPDATE public.escrow_holds SET status = 'refunded', refund_requested = true, refund_amount = v_refund_request.refund_amount WHERE order_id = v_refund_request.order_id;
  
  INSERT INTO public.payment_transactions (order_id, transaction_type, amount, currency, status, initiated_by, notes) 
  VALUES (v_refund_request.order_id, 'refund', v_refund_request.refund_amount, (SELECT currency FROM public.orders WHERE id = v_refund_request.order_id), 'pending', p_approved_by, 'Refund request #' || v_refund_request.id) 
  RETURNING id INTO v_transaction_id;
  
  UPDATE public.refund_requests SET status = 'processed', processed_at = NOW(), refund_transaction_id = v_transaction_id WHERE id = p_refund_request_id;
  UPDATE public.orders SET status = 'refunded' WHERE id = v_refund_request.order_id;
  
  RETURN v_transaction_id;
END;
$function$
;
