CREATE OR REPLACE FUNCTION public.initiate_refund_secure(p_refund_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_admin_id UUID;
BEGIN
  -- Verify caller is admin
  IF auth.uid() IS NULL THEN
     RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  SELECT user_id INTO v_admin_id
  FROM public.users
  WHERE user_id = auth.uid()
  AND (user_metadata->>'is_admin')::boolean = true;
  
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Access denied: Admins only';
  END IF;

  -- Call the original function or execute logic
  -- We'll reuse the logic but pass auth.uid() as the approver
  RETURN public.initiate_refund(p_refund_request_id, auth.uid());
END;
$function$
;
