CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Check for 'admin' role in JWT metadata. 
  -- If metadata is missing or role is not admin, returns false.
  -- absolutely NO SQL queries here.
  RETURN COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'user_type') = 'admin',
    false
  );
END;
$function$
;
