CREATE OR REPLACE FUNCTION public.process_automatic_releases()
 RETURNS TABLE(released_count integer, total_amount_released numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_released_count INTEGER := 0;
  v_total_amount NUMERIC := 0;
  v_hold RECORD;
BEGIN
  FOR v_hold IN
    SELECT eh.id, eh.order_id, eh.partner_id, eh.partner_payout, eh.currency
    FROM public.escrow_holds eh
    WHERE eh.status = 'held' AND eh.auto_release_enabled = true AND eh.manual_review_required = false AND eh.scheduled_release_date <= NOW() AND eh.refund_requested = false
  LOOP
    IF validate_partner_payment_info(v_hold.partner_id) THEN
      UPDATE public.escrow_holds SET status = 'released', released_at = NOW() WHERE id = v_hold.id;
      UPDATE public.orders SET status = 'completed', payment_released = true, payment_released_at = NOW() WHERE id = v_hold.order_id;
      INSERT INTO public.payment_transactions (order_id, transaction_type, amount, currency, status, released_to_partner, released_at, notes) 
      VALUES (v_hold.order_id, 'release', v_hold.partner_payout, v_hold.currency, 'completed', true, NOW(), 'Automatic release after hold period');
      
      v_released_count := v_released_count + 1;
      v_total_amount := v_total_amount + v_hold.partner_payout;
    ELSE
      UPDATE public.escrow_holds SET manual_review_required = true WHERE id = v_hold.id;
    END IF;
  END LOOP;
  RETURN QUERY SELECT v_released_count, v_total_amount;
END;
$function$
;
