CREATE OR REPLACE FUNCTION public.protect_user_roles()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- If not an admin, don't allow changing user_type or approved status
  IF NOT public.is_admin() THEN
    IF NEW.user_type <> OLD.user_type THEN
      RAISE EXCEPTION 'You do not have permission to change your user role.';
    END IF;
    IF NEW.approved <> OLD.approved THEN
      RAISE EXCEPTION 'You do not have permission to change your approval status.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
