CREATE OR REPLACE FUNCTION public.recalculate_all_partner_metrics()
 RETURNS TABLE(processed_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_partner RECORD; v_count INTEGER := 0;
BEGIN
  FOR v_partner IN SELECT DISTINCT seller_id FROM public.orders WHERE seller_id IS NOT NULL LOOP
    PERFORM calculate_partner_metrics(v_partner.seller_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN QUERY SELECT v_count;
END;
$function$
;
