CREATE OR REPLACE FUNCTION public.trigger_calculate_release_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  base_hold_days INTEGER := 7;
  final_hold_days INTEGER;
  high_value_threshold NUMERIC;
BEGIN
  IF NEW.status = 'delivered' AND (OLD IS NULL OR OLD.status != 'delivered') THEN
    high_value_threshold := COALESCE(
      (SELECT value::NUMERIC FROM public.system_config WHERE key = 'high_value_threshold'),
      1000
    );
    
    IF NEW.total_amount > high_value_threshold THEN
      final_hold_days := COALESCE(
        (SELECT value::INTEGER FROM public.system_config WHERE key = 'high_value_hold_days'),
        14
      );
    ELSE
      final_hold_days := COALESCE(
        (SELECT value::INTEGER FROM public.system_config WHERE key = 'escrow_hold_days'),
        7
      );
    END IF;
    
    UPDATE public.escrow_holds 
    SET 
      delivery_confirmed_at = NOW(),
      scheduled_release_date = NOW() + (final_hold_days || ' days')::INTERVAL,
      extended_hold_reason = CASE 
        WHEN NEW.total_amount > high_value_threshold THEN 'high_value'
        ELSE NULL
      END
    WHERE order_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;
