CREATE OR REPLACE FUNCTION public.trigger_create_escrow_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_platform_fee NUMERIC(12,2);
  v_platform_fee_percent NUMERIC(5,2);
BEGIN
  IF NEW.status = 'confirmed' AND (OLD IS NULL OR OLD.status != 'confirmed') THEN
    v_platform_fee_percent := COALESCE(
      (SELECT value::NUMERIC FROM public.system_config WHERE key = 'platform_fee_percent'),
      3.8
    );
    v_platform_fee := NEW.total_amount * (v_platform_fee_percent / 100);
    
    INSERT INTO public.escrow_holds (order_id, partner_id, total_amount, platform_fee, partner_payout, currency, status) 
    VALUES (NEW.id, NEW.seller_id, NEW.total_amount, v_platform_fee, NEW.total_amount - v_platform_fee, NEW.currency, 'held');
    
    INSERT INTO public.payment_transactions (order_id, transaction_type, amount, currency, status, held_in_escrow, initiated_by) 
    VALUES (NEW.id, 'hold', NEW.total_amount, NEW.currency, 'completed', true, NEW.buyer_id);
  END IF;
  RETURN NEW;
END;
$function$
;
