-- POLICIES: agent_partner_agreements
-- =============================================================================
DROP POLICY IF EXISTS "Agreements are viewable by admins, the agent, and the partner." ON public.agent_partner_agreements;
CREATE POLICY "Agreements are viewable by admins, the agent, and the partner." ON public.agent_partner_agreements FOR SELECT TO {public}
  USING (((EXISTS ( SELECT 1
   FROM sales_agents
  WHERE ((sales_agents.id = agent_partner_agreements.agent_id) AND (sales_agents.user_id = auth.uid())))) OR (partner_id = auth.uid()) OR (((auth.jwt() -> 'app_metadata'::text) ->> 'user_type'::text) = 'admin'::text)));
-- =============================================================================
-- POLICIES: agent_partner_agreements
-- =============================================================================
DROP POLICY IF EXISTS "Only admins can delete agreements." ON public.agent_partner_agreements;
CREATE POLICY "Only admins can delete agreements." ON public.agent_partner_agreements FOR DELETE TO {public}
  USING ((((auth.jwt() -> 'app_metadata'::text) ->> 'user_type'::text) = 'admin'::text));
-- =============================================================================
-- POLICIES: agent_partner_agreements
-- =============================================================================
DROP POLICY IF EXISTS "Only admins can insert agreements." ON public.agent_partner_agreements;
CREATE POLICY "Only admins can insert agreements." ON public.agent_partner_agreements FOR INSERT TO {public}
  WITH CHECK ((((auth.jwt() -> 'app_metadata'::text) ->> 'user_type'::text) = 'admin'::text));
-- =============================================================================
-- POLICIES: agent_partner_agreements
-- =============================================================================
DROP POLICY IF EXISTS "Only admins can update agreements." ON public.agent_partner_agreements;
CREATE POLICY "Only admins can update agreements." ON public.agent_partner_agreements FOR UPDATE TO {public}
  USING ((((auth.jwt() -> 'app_metadata'::text) ->> 'user_type'::text) = 'admin'::text));
