-- POLICIES: users
-- =============================================================================
DROP POLICY IF EXISTS "Users can update limited profile fields" ON public.users;
CREATE POLICY "Users can update limited profile fields" ON public.users FOR UPDATE TO {authenticated}
  USING ((auth.uid() = user_id))
  WITH CHECK (((auth.uid() = user_id) AND (((( SELECT row_to_json(u.*) AS row_to_json
   FROM users u
  WHERE (u.user_id = auth.uid())) ->> 'user_type'::text) = user_type) AND ((( SELECT row_to_json(u.*) AS row_to_json
   FROM users u
  WHERE (u.user_id = auth.uid())) ->> 'approved'::text) = (approved)::text))));
